    i = 0
    while i < len(text):
        if text[i] == ' ':
            if i + 1 < len(text) and text[i + 1] == ' ':
                if i + 2 < len(text) and text[i + 2] == ' ':
                    result.append('-')
                    i += 3
                else:
                    result.append('-')
                    i += 2
            else:
